import ast,copy,hashlib,json
from pathlib import Path
p=json.load(open('proposal.json')); r=json.load(open('runtime.json')); w=json.load(open('workspace.json'))
def validate(value,schema,path='"'$'"'):
 t=schema.get('type')
 if t=='object':
  assert isinstance(value,dict),(path,t)
  assert set(schema.get('required',[]))<=set(value),(path,'missing fields')
  props=schema.get('properties',{})
  if schema.get('additionalProperties') is False: assert set(value)<=set(props),(path,'extra fields')
  for k,v in value.items():
   if k in props: validate(v,props[k],path+'.'+k)
 elif t=='array':
  assert isinstance(value,list),(path,t)
  assert len(value)>=schema.get('minItems',0),(path,'minItems')
  for i,v in enumerate(value): validate(v,schema.get('items',{}),path+f'[{i}]')
 elif t=='string': assert isinstance(value,str) and len(value)>=schema.get('minLength',0),(path,t)
 elif t=='boolean': assert type(value) is bool,(path,t)
 if 'enum' in schema: assert value in schema['enum'],(path,'enum')
 if 'const' in schema: assert type(value) is type(schema['const']) and value==schema['const'],(path,'const')
validate(p['study'],r['study_schema'])
assert p['parent_trial'] in r['context']['allowed_observation_ids']
assert set(p['study']['evidence_refs'])<=set(r['context']['allowed_observation_ids'])
assert p['study']['protocol_ref']==r['required_study_protocol_ref']==w['protocol_hash']
assert 1<=len(p['variants'])<=4 and any(v['role']=='candidate' for v in p['variants'])
assert len({v['name'] for v in p['variants']})==len(p['variants'])
assert len({v['file'] for v in p['variants']})==len(p['variants'])
parent=ast.parse(Path('history_g3_r0040_task_direct.py').read_text())
parent_class=next(n for n in parent.body if isinstance(n,ast.ClassDef) and n.name=='Model')
parent_methods={n.name:ast.dump(n,include_attributes=False) for n in parent_class.body if isinstance(n,ast.FunctionDef)}
normalized=[]
for v in p['variants']:
 file=v['file']; assert Path(file).name==file and file.endswith('.py')
 source=Path(file).read_text(); tree=ast.parse(source); compile(source,file,'exec')
 cfg=next(ast.literal_eval(n.value) for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets))
 assert cfg==v['config']
 assert not (set(cfg)&{'epochs','batch_size','train_seed','dense_learning_rate','sparse_learning_rate','history_limit','precision'})
 model=next(n for n in tree.body if isinstance(n,ast.ClassDef) and n.name=='Model')
 init=next(n for n in model.body if isinstance(n,ast.FunctionDef) and n.name=='__init__')
 defaults={arg.arg:ast.literal_eval(d) for arg,d in zip(init.args.args[-len(init.args.defaults):],init.args.defaults)}
 for k,val in cfg.items():
  assert k in defaults,k
  left=list(defaults[k]) if isinstance(defaults[k],tuple) else defaults[k]
  assert left==val,(file,k,left,val)
 for n in model.body:
  if isinstance(n,ast.FunctionDef) and n.name not in ('__init__','forward'):
   assert ast.dump(n,include_attributes=False)==parent_methods[n.name],(file,n.name,'unexpected inherited change')
 for n in ast.walk(tree):
  if isinstance(n,ast.Import):
   assert all(x.name.split('.')[0] in {'torch','numpy','math','typing','copy','functools','collections','itertools','dataclasses','contextlib','unirank','model_zoo'} for x in n.names)
  if isinstance(n,ast.ImportFrom): assert n.module.split('.')[0] in {'torch','numpy','math','typing','copy','functools','collections','itertools','dataclasses','contextlib','unirank','model_zoo'}
  if isinstance(n,ast.Call) and isinstance(n.func,ast.Name): assert n.func.id not in {'open','exec','eval','compile','__import__','input'}
 digest=hashlib.sha256(source.encode()).hexdigest(); assert digest in v['note']
 norm=copy.deepcopy(tree)
 for n in norm.body:
  if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets): n.value=ast.Constant(None)
 norm_model=next(n for n in norm.body if isinstance(n,ast.ClassDef) and n.name=='Model')
 norm_init=next(n for n in norm_model.body if isinstance(n,ast.FunctionDef) and n.name=='__init__')
 for i,arg in enumerate(norm_init.args.args[-len(norm_init.args.defaults):]):
  if arg.arg in {'centering_scope','auxiliary_reduction_precision'}: norm_init.args.defaults[i]=ast.Constant(None)
 normalized.append(ast.dump(norm,include_attributes=False))
 print(file,'syntax/config/defaults/imports/ancestor-methods: PASS',digest)
assert len(set(normalized))==1,'Unexpected executable differences across factorial'
for a in w['available_ancestor_sources']:
 assert hashlib.sha256(Path(a['file']).read_bytes()).hexdigest()==a['source_sha256'],a['file']
assert hashlib.sha256(Path('baseline_reference.py').read_bytes()).hexdigest()=='f4b473cbacf60d72cff90f3721ad754dd617ee6065fe3fca2fc9cd4be2b25c36'
assert {x['knowledge_id'] for x in p['knowledge_assessments']}=={'unirank-method-infnet','unirank-method-tokenmixer'}
